select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('governance-code','کد برنامه حاکمیت','text',true,10,'{}'),('governance-title','عنوان برنامه','text',true,20,'{}'),('scope','دامنه حاکمیت','select',true,30,'{"options":["کل سازمان","واحد سازمانی","گروه اسناد","پوشه","نوع سند"]}'),('scope-reference','مرجع دامنه','text',false,40,'{}'),('owner','مالک حاکمیت','text',true,50,'{}'),('manager','مسئول اجرا','text',false,60,'{}'),('policy-reference','مرجع خط‌مشی','text',false,70,'{}'),('review-cycle','دوره بازبینی','select',true,80,'{"options":["ماهانه","فصلی","شش‌ماهه","سالانه","موردی"]}'),('last-review-date','آخرین بازبینی','text',false,90,'{}'),('next-review-date','بازبینی بعدی','text',false,100,'{}'),('coverage-percent','درصد پوشش','number',false,110,'{}'),('compliance-percent','درصد انطباق','number',false,120,'{}'),('open-findings','مغایرت‌های باز','number',false,130,'{}'),('high-risk-findings','مغایرت‌های پرریسک','number',false,140,'{}'),('governance-status','وضعیت برنامه','select',true,150,'{"options":["پیش‌نویس","فعال","در حال بازبینی","نیازمند اقدام","منطبق","تعلیق شده","مختومه"]}'),('action-plan','برنامه اقدام','textarea',false,160,'{}'),('notes','یادداشت','textarea',false,170,'{}')
) v(k,t,ft,r,s,o) where m.code='50-document-governance' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
