insert into platform_modules(code,title,is_active) values ('50-document-governance','مرکز حاکمیت مستندات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده برنامه','modules:50-document-governance:read'),('write','ثبت برنامه','modules:50-document-governance:write'),('delete','حذف برنامه','modules:50-document-governance:delete'),('review','بازبینی','modules:50-document-governance:review'),('assess','ارزیابی حاکمیت','modules:50-document-governance:assess'),('action','ثبت برنامه اقدام','modules:50-document-governance:action'),('close','مختومه کردن','modules:50-document-governance:close')) v(a,t,p) where m.code='50-document-governance' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;